(function () {
  const css = `
    .skills__container {
      align-items: start !important;
    }

    .skills__content.skills__open {
      grid-column: auto !important;
    }

    .skills__content.skills__open .skills__list {
      grid-template-columns: 1fr !important;
      max-width: none !important;
      width: 100% !important;
    }

    .skills__content.skills__open {
      min-height: auto !important;
    }

    .portfolio__container {
      max-width: 980px !important;
      padding: .75rem 1rem 1rem !important;
      overflow: hidden !important;
    }

    .portfolio__content {
      width: min(100%, 840px) !important;
      min-height: 400px !important;
      padding: 1.85rem !important;
      gap: 1.65rem !important;
      grid-template-columns: minmax(270px, .95fr) minmax(280px, 1.05fr) !important;
      box-shadow: 0 28px 72px rgba(15, 23, 42, .22) !important;
    }

    .portfolio__content::before {
      right: 1.55rem !important;
      bottom: 1.6rem !important;
      width: 8.2rem !important;
      height: 8.2rem !important;
      border-radius: 1.65rem !important;
    }

    .portfolio__content::after {
      right: 6.5rem !important;
      bottom: 1.65rem !important;
      width: 7rem !important;
      height: 9rem !important;
      border-radius: 1.25rem !important;
    }

    .portfolio__img {
      width: min(100%, 380px) !important;
      height: 255px !important;
      transform: translateX(2.5rem) translateY(-.2rem) rotate(.5deg) !important;
    }

    .portfolio__title {
      font-size: clamp(1.25rem, 1.7vw, 1.65rem) !important;
    }

    .portfolio__description {
      font-size: .9rem !important;
      line-height: 1.62 !important;
    }

    .portfolio__tech {
      display: flex !important;
      flex-direction: column !important;
      align-items: flex-start !important;
      gap: .55rem !important;
      margin-bottom: 1.15rem !important;
      max-width: 100% !important;
    }

    .portfolio__tech strong {
      display: block !important;
      flex-basis: auto !important;
      margin: 0 !important;
      color: #8bd9ee !important;
      font-size: .72rem !important;
      letter-spacing: .08em !important;
      text-transform: uppercase !important;
    }

    .portfolio__tech-chips {
      display: flex !important;
      flex-wrap: wrap !important;
      align-items: center !important;
      gap: .45rem !important;
      max-width: 100% !important;
    }

    .portfolio__tech-chip {
      display: inline-flex !important;
      align-items: center !important;
      border: 1px solid rgba(255, 255, 255, .15) !important;
      border-radius: 999px !important;
      background: rgba(255, 255, 255, .09) !important;
      color: #e8f7ff !important;
      font-size: .7rem !important;
      font-weight: 750 !important;
      line-height: 1 !important;
      padding: .4rem .58rem !important;
      white-space: nowrap !important;
    }

    .location.section {
      padding-top: 3rem !important;
      padding-bottom: 2.25rem !important;
    }

    .location__container {
      margin-top: 1.15rem !important;
    }

    .location__panel,
    .location__map-card {
      min-height: 18rem !important;
      box-shadow: 0 24px 58px rgba(15, 23, 42, .12) !important;
    }

    .location__map-card {
      min-height: 23rem !important;
    }

    .location__nz-visual {
      position: relative !important;
      min-height: 11.5rem !important;
      height: 11.5rem !important;
      margin: .75rem 0 !important;
    }

    .location__nz-img {
      display: none !important;
    }

    .location__nz-svg {
      position: relative;
      width: 13rem;
      height: 14rem;
      isolation: isolate;
      animation: locationFloat 5s ease-in-out infinite;
    }

    .location__nz-svg::before {
      content: '';
      position: absolute;
      inset: 1rem;
      border-radius: 2rem;
      background:
        radial-gradient(circle at 68% 34%, rgba(239, 68, 68, .16), transparent 0 1.25rem, transparent 1.26rem),
        radial-gradient(circle at 55% 48%, rgba(14, 165, 216, .14), transparent 0 2.8rem, transparent 2.81rem);
      filter: blur(.2px);
      z-index: -1;
    }

    .location__map {
      height: 15.5rem !important;
    }

    .location__route-panel {
      padding: .7rem !important;
      margin-bottom: .7rem !important;
      gap: .5rem !important;
    }

    .location__route-input,
    .location__route-button {
      padding: .65rem .8rem !important;
    }

    .location__weather {
      gap: .8rem 1.1rem !important;
    }

    .location__weather-card {
      padding: .8rem !important;
      border-radius: .9rem !important;
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, .9), 0 12px 26px rgba(15, 23, 42, .07) !important;
    }

    .location__weather-card span {
      font-size: .72rem !important;
      margin-bottom: .25rem !important;
    }

    .location__weather-card strong {
      font-size: 1.32rem !important;
    }

    .location__updated {
      font-size: .78rem !important;
      line-height: 1.45 !important;
    }

    #location [data-aos] {
      transition-duration: .52s !important;
    }

    .location__island {
      position: absolute;
      display: block;
      background: linear-gradient(135deg, #7ed7e5 0%, #2d98b5 48%, #166a82 100%);
      box-shadow: 0 18px 28px rgba(15, 23, 42, .18);
    }

    .location__island--north {
      width: 4.6rem;
      height: 7.35rem;
      right: 3.15rem;
      top: 1.05rem;
      border-radius: 62% 38% 58% 42% / 48% 52% 48% 52%;
      transform: rotate(26deg);
    }

    .location__island--north::after {
      content: '';
      position: absolute;
      width: 1.55rem;
      height: 2.4rem;
      right: -.7rem;
      bottom: .85rem;
      border-radius: 55% 45% 60% 40%;
      background: linear-gradient(135deg, #8be1ea, #2b95ad);
      transform: rotate(-22deg);
      box-shadow: 0 16px 24px rgba(15, 23, 42, .14);
    }

    .location__island--south {
      width: 3.45rem;
      height: 7.55rem;
      left: 2.55rem;
      bottom: 1.15rem;
      border-radius: 54% 46% 56% 44% / 44% 56% 44% 56%;
      transform: rotate(37deg);
    }

    .location__pin {
      position: absolute;
      right: 3.1rem;
      top: 4.7rem;
      width: 1.7rem;
      height: 1.7rem;
      border-radius: 50% 50% 50% 0;
      background: #ef4444;
      transform: rotate(-45deg);
      box-shadow: 0 0 0 .55rem rgba(239, 68, 68, .16), 0 12px 20px rgba(239, 68, 68, .2);
      z-index: 3;
    }

    .location__pin::after {
      content: '';
      position: absolute;
      inset: .48rem;
      border-radius: 50%;
      background: #fff;
    }

    .location__route-line,
    .leaflet-overlay-pane path[stroke="#102033"] {
      stroke-dasharray: 10 12 !important;
      animation: routeDash 1.25s linear infinite;
    }

    @keyframes routeDash {
      to {
        stroke-dashoffset: -44;
      }
    }

    @media (max-width: 900px) {
      .skills__content.skills__open {
        grid-column: auto !important;
      }

      .portfolio__content {
        width: 100% !important;
        min-height: auto !important;
        padding: 1rem !important;
      }

      .portfolio__img {
        width: 100% !important;
        height: 220px !important;
        transform: none !important;
      }

      .portfolio__content::after {
        display: none !important;
      }

      .location__panel,
      .location__map-card,
      .location__weather {
        min-height: auto !important;
        transform: none !important;
      }
    }
  `;

  function injectStyle() {
    document.getElementById('site-fixes-style')?.remove();
    const style = document.createElement('style');
    style.id = 'site-fixes-style';
    style.textContent = css;
    document.head.appendChild(style);
  }

  function buildNzMap() {
    const visual = document.querySelector('.location__nz-visual');
    if (!visual || visual.querySelector('.location__nz-svg')) return;

    visual.innerHTML = `
      <div class="location__nz-svg" role="img" aria-label="Stylized map of New Zealand with Pukekohe marker">
        <span class="location__island location__island--north"></span>
        <span class="location__island location__island--south"></span>
        <span class="location__pin"></span>
      </div>
    `;
  }

  function formatDriveTime(km) {
    const mins = Math.max(5, Math.round((km / 65) * 60));
    if (mins >= 60) {
      const hours = Math.floor(mins / 60);
      const rest = mins % 60;
      return rest ? `${hours} hr ${rest} min` : `${hours} hr`;
    }
    return `${mins} min`;
  }

  function fixPortfolioTech() {
    document.querySelectorAll('.portfolio__tech').forEach((tech) => {
      const existingChips = Array.from(tech.querySelectorAll('.portfolio__tech-chip'));
      if (tech.querySelector('.portfolio__tech-chips')) return;

      const label = tech.querySelector('strong') || document.createElement('strong');
      label.textContent = 'Tech Used:';

      const chipRow = document.createElement('span');
      chipRow.className = 'portfolio__tech-chips';

      if (existingChips.length) {
        existingChips.forEach((chip) => chipRow.appendChild(chip));
      } else {
        const raw = tech.textContent.replace(/Tech Used:/i, '').replace(/\s+/g, ' ').trim();
        raw.split(',').map((item) => item.trim()).filter(Boolean).forEach((item) => {
          const chip = document.createElement('span');
          chip.className = 'portfolio__tech-chip';
          chip.textContent = item;
          chipRow.appendChild(chip);
        });
      }

      tech.innerHTML = '';
      tech.append(label, chipRow);
    });
  }

  function tuneLocationReveal() {
    const location = document.getElementById('location');
    if (!location) return;

    location.querySelectorAll('.location__panel, .location__map-card, [data-aos]').forEach((el, index) => {
      el.setAttribute('data-aos', 'fade-up');
      el.setAttribute('data-aos-offset', '45');
      el.setAttribute('data-aos-delay', String(Math.min(index * 35, 90)));
      el.setAttribute('data-aos-duration', '520');
    });

    if (window.AOS) {
      window.AOS.init({ offset: 80, duration: 650, once: false });
      if (window.AOS.refreshHard) window.AOS.refreshHard();
      else if (window.AOS.refresh) window.AOS.refresh();
    }
  }

  function enhanceRouteResult() {
    const output = document.getElementById('routeResult');
    if (!output || output.dataset.driveObserver === 'true') return;

    const observer = new MutationObserver(() => {
      const match = output.textContent.match(/Approx\.\s*([\d.]+)\s*km from Pukekohe\.?/i);
      if (!match || /drive/i.test(output.textContent)) return;

      const km = Number(match[1]);
      if (!Number.isFinite(km)) return;

      output.textContent = `Approx. ${km.toFixed(1)} km from Pukekohe - about ${formatDriveTime(km)} drive.`;

      document
        .querySelectorAll('.leaflet-overlay-pane path')
        .forEach((path) => path.classList.add('location__route-line'));
    });

    observer.observe(output, { childList: true, characterData: true, subtree: true });
    output.dataset.driveObserver = 'true';
  }

  function runFixes() {
    injectStyle();
    buildNzMap();
    fixPortfolioTech();
    tuneLocationReveal();
    enhanceRouteResult();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', runFixes);
  } else {
    runFixes();
  }

  setTimeout(runFixes, 400);
  setTimeout(runFixes, 1400);
  setTimeout(runFixes, 2600);
  setTimeout(runFixes, 4200);
})();
